  BIND(?product AS ?lightestProduct)
  FILTER(?weight = (SELECT MAX(?w) FROM { ?p a pv:Hardware ; pv:weight_g ?w . }))
  BIND(?product AS ?heaviestProduct)
} GROUP BY ?category

