       pv:hasBomPart ?part ;
       pv:quantity ?quantity .
  ?part pv:hasProduct ?component ;
         pv:quantity ?compQuantity .
  ?component pv:price ?compPrice .
  BIND(?compPrice * ?compQuantity AS ?totalCompCost)
